-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 11
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 11 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 11', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 11 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-11.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Nomeie as quatro etapas do ciclo, na ordem em que acontecem.', 0.2, 'As quatro etapas, na ordem: Entender, Criar, Testar e Melhorar. O aluno pode citar as etapas com o nome exato ou com equivalente claro do ciclo.', 'Nota cheia: cita as quatro etapas na ordem correta (Entender, Criar, Testar, Melhorar). Metade: cita as quatro etapas, mas fora de ordem, ou cita três etapas corretas. Zero: em branco, cita etapas que não são do ciclo ou não nomeia nenhuma.'),
      (v_atividade, 1, 2, 'Explique o que se faz em cada etapa, aplicado à tela de agendamento.', 0.4, 'Entender: mapear objetivos e necessidades reais de quem vai usar a tela (ex.: pacientes que acham confusa a marcação pelo celular). Criar: desenhar protótipos rápidos da agenda, com botões, campos e hierarquia visual. Testar: observar pessoas reais marcando consultas, sem dar dicas. Melhorar: redesenhar o que foi confuso e produzir a Versão 2 com base nas evidências.', 'Nota cheia: explica o objetivo das quatro etapas aplicado à tela de agendamento, com as palavras do aluno. Metade: explica de forma geral, sem ligar a etapa à tela de agendamento, ou esquece uma etapa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 3, 'Explique por que o ciclo volta ao início e não termina na entrega da primeira versão.', 0.4, 'O ciclo volta ao início porque cada teste gera aprendizado novo; a Versão 2 também tem falhas a descobrir e a nova rodada começa de novo a partir da compreensão do problema. O produto evolui por aprimoramento, e não termina na primeira entrega.', 'Nota cheia: explica que o ciclo é iterativo, que o aprendizado de cada teste alimenta a rodada seguinte e que a primeira entrega é só o começo. Metade: diz que o ciclo se repete, mas sem explicar o motivo (o aprendizado). Zero: em branco, errado ou diz que o processo termina na entrega.'),
      (v_atividade, 2, 1, 'Descreva a principal premissa do modelo linear.', 0.2, 'No modelo linear, tudo pode ser previsto no início do projeto, e as falhas de usabilidade só aparecem depois do lançamento definitivo.', 'Nota cheia: diz que o linear parte da premissa de que tudo é previsível no início e que as falhas só aparecem após o lançamento. Metade: descreve só uma das duas ideias. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 2, 'Descreva como o modelo iterativo trata as falhas de usabilidade encontradas no uso.', 0.4, 'O modelo iterativo encara o projeto como uma espiral de aprendizado: a falha encontrada no uso vira dado de projeto e é corrigida na rodada seguinte, com nova versão testada.', 'Nota cheia: explica que a falha é observada no teste, vira evidência e é corrigida na rodada seguinte. Metade: diz que a falha é corrigida, mas sem ligar à rodada seguinte ou à evidência. Zero: em branco, errado ou descreve o modelo linear.'),
      (v_atividade, 2, 3, 'Defenda sua escolha, usando o risco de uma falha descoberta só após o lançamento.', 0.4, 'A tela de agendamento deve usar o modelo iterativo, porque uma falha descoberta só após o lançamento causa prejuízo e perda de confiança dos pacientes. Testar cedo, com protótipos, permite corrigir o problema antes da entrega definitiva.', 'Nota cheia: escolhe o modelo iterativo e usa o risco da falha descoberta só após o lançamento como argumento. Metade: escolhe o iterativo, mas sem usar o risco do lançamento como argumento. Zero: em branco, escolhe o linear sem justificativa ou fica fora do tema.'),
      (v_atividade, 3, 1, 'Explique de quem é, segundo a aula, a responsabilidade pelo clique no lugar errado.', 0.2, 'Segundo a aula, a responsabilidade é da interface, e não do usuário: o erro é da pista visual que a tela forneceu, e não de quem clicou.', 'Nota cheia: diz que a responsabilidade é da interface (pista visual), e não do voluntário. Metade: diz que não é culpa do voluntário, mas sem indicar a pista visual. Zero: em branco, culpa o usuário ou fica fora do tema.'),
      (v_atividade, 3, 2, 'Explique por que o erro é considerado dado de projeto e não fracasso.', 0.4, 'O erro é dado de projeto porque revela um ponto cego da versão inicial, mostrando exatamente o que precisa ser corrigido antes que a falha custe mais caro no código pronto.', 'Nota cheia: explica que o erro aponta o que corrigir, revelando um ponto cego, e que isso evita custo maior depois. Metade: diz que o erro ajuda a melhorar, sem explicar o ponto cego ou o custo. Zero: em branco, diz que o erro é fracasso ou fica fora do tema.'),
      (v_atividade, 3, 3, 'Indique a ação que a equipe deve tomar a partir desse achado.', 0.4, 'A equipe deve ajustar a pista visual do botão (destaque, posição ou contraste) e, se possível, repetir o teste com a Versão 2 para confirmar a correção.', 'Nota cheia: indica ajuste na interface (destaque ou posicionamento do elemento) e uma nova verificação por teste. Metade: indica o ajuste, sem a nova verificação. Zero: em branco, sugere ignorar o achado ou explicar o usuário.'),
      (v_atividade, 4, 1, 'Cite três tipos de evidência coletados durante o teste.', 0.2, 'Três entre: tempo e hesitação, cliques falsos e perguntas verbais (ex.: "para onde eu vou agora?").', 'Nota cheia: cita três tipos de evidência corretos da aula. Metade: cita um ou dois tipos corretos. Zero: em branco ou cita tipos que não são da aula.'),
      (v_atividade, 4, 2, 'Explique o que indica a hesitação do usuário antes de achar um botão.', 0.4, 'A hesitação indica falta de destaque do botão ou texto confuso, isto é, a interface não comunica bem a ação seguinte.', 'Nota cheia: liga a hesitação à falta de destaque ou ao texto confuso. Metade: diz que a hesitação mostra dificuldade, sem apontar a causa na interface. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 3, 'Explique o que indica uma pergunta do tipo "para onde eu vou agora?".', 0.4, 'A pergunta "para onde eu vou agora?" indica que a navegação falhou em mostrar o próximo passo lógico da tarefa.', 'Nota cheia: diz que a navegação não indica o próximo passo. Metade: diz que há problema de navegação, sem explicar o próximo passo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 1, 'Classifique cada comentário como opinião subjetiva ou evidência objetiva.', 0.2, 'O comentário sobre a cor ("achava feia") é opinião subjetiva. O comentário sobre o voluntário que levou quarenta segundos e clicou duas vezes em texto fixo é evidência objetiva.', 'Nota cheia: classifica corretamente os dois comentários (opinião e evidência). Metade: classifica só um dos dois corretamente. Zero: em branco ou classifica os dois do mesmo jeito.'),
      (v_atividade, 5, 2, 'Explique por que a opinião não serve, isoladamente, como critério técnico.', 0.4, 'A opinião depende do gosto pessoal, que muda de pessoa para pessoa, e não mostra um impedimento real na tarefa; por isso não serve sozinha como critério técnico.', 'Nota cheia: explica que a opinião depende do gosto e varia de pessoa para pessoa, e que não mostra impedimento real. Metade: diz que a opinião é subjetiva, sem explicar a variação ou a falta de impedimento real. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 3, 'Explique qual ação o designer deve tomar diante da evidência objetiva.', 0.4, 'Diante da evidência objetiva, o designer deve agir para corrigir o problema, por exemplo ajustando o contraste ou o posicionamento do botão ou do texto fixo.', 'Nota cheia: indica ação técnica de correção (contraste ou posicionamento) diante da evidência. Metade: indica uma ação genérica, como "melhorar a tela", sem ligar à evidência. Zero: em branco, ignorar a evidência ou fora do tema.'),
      (v_atividade, 6, 1, 'Explique o que a Versão 1 representa, em termos de hipótese.', 0.2, 'A Versão 1 é uma hipótese inicial: uma proposta testável do fluxo básico, que precisa ser validada com pessoas reais para saber se o usuário consegue concluir a tarefa.', 'Nota cheia: diz que a Versão 1 é hipótese a ser testada com o usuário. Metade: diz que é um primeiro esboço, sem falar em hipótese ou teste. Zero: em branco, diz que é o produto final ou fica fora do tema.'),
      (v_atividade, 6, 2, 'Explique qual é a regra de projeto aplicada à Versão 1.', 0.4, 'A regra de projeto é que a Versão 1 precisa ser testável e completa nos recursos essenciais, e não bonita.', 'Nota cheia: cita a regra (testável e completa em recursos essenciais). Metade: cita só uma das duas exigências (testável ou completa). Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 3, 'Justifique por que a Versão 1 não precisa ser bonita para cumprir seu papel.', 0.4, 'A beleza não cumpre o papel da Versão 1, que é validar o fluxo básico. Uma tela feia, mas completa e testável, já mostra se o usuário consegue concluir a marcação.', 'Nota cheia: explica que o papel é validar o fluxo e que a aparência não é necessária para isso. Metade: diz que não precisa ser bonita, sem explicar o papel de validação. Zero: em branco, diz que a Versão 1 precisa ser bonita ou fica fora do tema.'),
      (v_atividade, 7, 1, 'Descreva o problema do calendário no celular.', 0.2, 'Os dias do calendário ficavam muito pequenos no celular e eram difíceis de tocar com o polegar, o que gera toques errados na data.', 'Nota cheia: descreve os dias pequenos e a dificuldade de toque com o polegar. Metade: descreve só o tamanho pequeno, sem ligar ao toque. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 2, 'Descreva o problema do botão de confirmação e explique por que ele atrapalha.', 0.4, 'O botão de confirmação estava com cor cinza, que se misturava ao fundo da tela, então não era identificado como ação principal, e o usuário demorava a concluir a marcação.', 'Nota cheia: descreve a falta de destaque (cinza misturado ao fundo) e explica que isso atrapalha a identificação da ação principal. Metade: descreve a falta de destaque, sem explicar o efeito na tarefa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique por que a falta de confirmação gera insegurança no usuário.', 0.4, 'Sem a confirmação das etapas, o usuário não sabe se o horário escolhido já está reservado ou se a marcação foi feita, e por isso fica inseguro.', 'Nota cheia: liga a falta de confirmação à dúvida sobre a reserva ou a conclusão. Metade: diz que gera insegurança, sem explicar a dúvida concreta. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 1, 'Indique qual falha teve o maior percentual de relatos de atrito.', 0.2, 'A falha com maior percentual de relatos de atrito foi o botão invisível, com 80%.', 'Nota cheia: indica "botão invisível" com 80%. Metade: indica o botão invisível sem o percentual, ou o percentual certo sem nomear a falha. Zero: em branco ou indica outra falha.'),
      (v_atividade, 8, 2, 'Explique por que o percentual deve orientar a ordem das correções, e não a opinião de quem fez a tela.', 0.4, 'O percentual vem de dados observados em testes com voluntários, mostrando onde o problema atinge mais pessoas. A opinião de quem fez a tela é um palpite e pode não refletir o uso real.', 'Nota cheia: diz que o percentual é dado observado e que a opinião de quem fez a tela não comprova o problema real. Metade: diz que o dado é mais confiável que a opinião, sem explicar o porquê. Zero: em branco, defende a opinião do designer ou fica fora do tema.'),
      (v_atividade, 8, 3, 'Explique qual relação existe entre o botão invisível e o toque errado.', 0.4, 'Há relação de causa e efeito: o botão pouco visível faz o usuário tocar em outro lugar, o que gera o toque errado. Parte dos toques errados decorre da falta de destaque do botão.', 'Nota cheia: explica que o botão invisível causa o toque errado (causa e efeito). Metade: diz que os dois estão relacionados, sem explicar a causa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 1, 'Explique o que significa transformar um achado de teste em decisão.', 0.2, 'Transformar achado em decisão é definir uma mudança concreta na tela que responda a um problema observado no teste.', 'Nota cheia: explica que é definir uma mudança concreta de tela a partir de um problema observado. Metade: diz que é "resolver o problema", sem a mudança concreta. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 2, 'Dê um exemplo de achado e a decisão visual correspondente.', 0.4, 'Exemplo: achado "botão de confirmação sem destaque" leva à decisão de usar um botão primário com alto contraste (cor ciano brilhante, texto escuro e largura total no pé da tela). Outro exemplo válido: calendário ilegível leva à troca por cards de horário.', 'Nota cheia: dá um achado e a decisão visual correspondente, coerentes entre si. Metade: dá a decisão, mas o achado é vago ou não corresponde. Zero: em branco, sem exemplo ou exemplo que não corresponde a um achado.'),
      (v_atividade, 9, 3, 'Explique por que cada decisão deve estar ligada a um problema observado.', 0.4, 'Cada decisão precisa estar ligada a um problema observado, para que a mudança tenha justificativa e não seja um palpite. Isso permite comprovar depois se a mudança resolveu o problema.', 'Nota cheia: explica que a decisão precisa de justificativa em fato observado e evita palpite. Metade: diz que a ligação é importante, sem explicar o palpite ou a comprovação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 1, 'Descreva o formato dos cards de horário proposto.', 0.2, 'Os cards de horário são botões largos, com os horários disponíveis (ex.: 14:00 e 15:30), no lugar do calendário condensado.', 'Nota cheia: descreve botões largos com horários disponíveis, no lugar do calendário. Metade: diz que são "cards" ou botões, sem descrever os horários ou a troca. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 2, 'Explique qual problema da Versão 1 esse formato resolve.', 0.4, 'Resolve o problema do calendário condensado da Versão 1, que era difícil de tocar com o polegar e gerava toques errados.', 'Nota cheia: liga os cards ao problema do calendário condensado e à dificuldade de toque. Metade: liga ao problema do calendário, sem citar a dificuldade de toque. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 3, 'Explique a relação entre a área de toque e a precisão do usuário ao escolher um horário.', 0.4, 'Uma área de toque maior, com mínimo de 44 pixels, reduz o erro de toque e aumenta a precisão, porque o polegar consegue acertar o horário desejado sem atingir o vizinho.', 'Nota cheia: explica que área maior reduz erro e aumenta a precisão ao escolher o horário (pode citar os 44 pixels). Metade: diz que área maior ajuda, sem explicar a precisão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 1, 'Explique por que a cor cinza atrapalhava a identificação do botão.', 0.2, 'A cor cinza se misturava ao fundo da tela, então o botão de confirmação não se destacava e os voluntários não o identificavam como a ação principal.', 'Nota cheia: explica que o cinza se confundia com o fundo e que isso impedia identificar a ação principal. Metade: diz que o cinza atrapalhava, sem explicar a mistura com o fundo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 2, 'Descreva a alteração feita na Versão 2 quanto à cor, ao texto e à largura do botão.', 0.4, 'Na Versão 2, o botão passou a ter cor ciano brilhante, texto escuro e largura total, ocupando a parte de baixo da tela.', 'Nota cheia: descreve as três alterações (cor ciano brilhante, texto escuro, largura total). Metade: descreve duas das três alterações. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 3, 'Explique a relação entre contraste e destaque da ação principal.', 0.4, 'Contraste alto entre o botão e o fundo faz a ação principal se destacar e chamar a atenção do usuário, orientando a conclusão da tarefa sem dúvidas.', 'Nota cheia: explica que o contraste faz a ação principal se destacar e orientar o usuário. Metade: diz que o contraste ajuda, sem ligar à ação principal. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 1, 'Cite as informações que devem aparecer no card de resumo.', 0.2, 'O card de resumo deve mostrar o médico, a data e o local, antes da confirmação final.', 'Nota cheia: cita médico, data e local. Metade: cita duas das três informações. Zero: em branco, cita informações que não são do resumo ou fica fora do tema.'),
      (v_atividade, 12, 2, 'Explique qual problema da Versão 1 esse card resolve.', 0.4, 'O card resolve o problema de os voluntários não saberem se o horário escolhido estava reservado, porque mostra as escolhas antes da confirmação.', 'Nota cheia: liga o card à dúvida sobre a reserva do horário. Metade: liga o card à insegurança, sem citar a reserva. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 3, 'Explique por que a confirmação de etapas reduz a insegurança do usuário.', 0.4, 'Confirmar cada etapa mostra ao usuário o que foi escolhido e se a marcação avançou, o que reduz a dúvida e a insegurança sobre o resultado.', 'Nota cheia: explica que a confirmação mostra o que foi escolhido e o avanço, reduzindo a dúvida. Metade: diz que confirmar dá segurança, sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 1, 'Indique o tempo médio de conclusão de cada versão.', 0.2, 'Versão 1: 68 segundos. Versão 2: 19 segundos.', 'Nota cheia: indica 68 s e 19 s corretamente. Metade: indica apenas um dos dois valores corretamente. Zero: em branco ou valores errados.'),
      (v_atividade, 13, 2, 'Calcule a redução percentual do tempo médio de conclusão, da Versão 1 para a Versão 2, e apresente o cálculo.', 0.4, 'Redução = (68 − 19) ÷ 68 × 100 = 49 ÷ 68 × 100 ≈ 72%. Aceitar arredondamentos próximos (71% a 72%), desde que o cálculo esteja apresentado.', 'Nota cheia: apresenta o cálculo correto e chega a cerca de 72% (ou 49 segundos sobre 68). Metade: apresenta o cálculo com erro de arredondamento ou de subtração, mas o método está certo. Zero: em branco, sem cálculo ou resultado errado com método errado.'),
      (v_atividade, 13, 3, 'Explique por que esses dados comprovam a melhoria e o que ainda não podem comprovar.', 0.4, 'Os dados comprovam a melhoria do tempo e da taxa de erro (de 35% para 2%) na mesma tarefa. Não podem comprovar, sozinhos, que a tela é agradável, que o usuário ficou satisfeito a longo prazo ou que o resultado vale para outras faixas de público, pois foram medidos em um grupo de testes.', 'Nota cheia: explica que os números comprovam a melhoria na tarefa medida e indica o que não comprovam (ex.: satisfação, amostra maior ou longo prazo). Metade: explica só o que comprovam, ou só o que não comprovam. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 1, 'Explique por que a preferência pessoal do designer não comprova a melhoria.', 0.2, 'A preferência pessoal do designer é opinião subjetiva. Ela depende do gosto e não mede se a tarefa ficou mais fácil para o usuário.', 'Nota cheia: explica que a preferência é subjetiva e não mede o resultado da tarefa. Metade: diz que é subjetiva, sem ligar ao resultado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 2, 'Explique por que a quantidade de recursos também não é, por si só, uma prova.', 0.4, 'A quantidade de recursos não prova melhoria, porque mais recursos podem aumentar a complexidade e o atrito. Uma versão só é melhor se o usuário conclui a tarefa com menos erro e em menos tempo.', 'Nota cheia: explica que mais recursos podem piorar a tarefa e que a prova está no resultado observado. Metade: diz que recursos não bastam, sem explicar a complexidade. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 3, 'Indique uma métrica objetiva que comprove a melhoria e explique o motivo da escolha.', 0.4, 'Uma métrica objetiva é o tempo médio de conclusão da tarefa (68 para 19 segundos) ou a taxa de erro nos toques (35% para 2%), porque ambas são medidas no uso real e comparáveis entre as versões.', 'Nota cheia: indica uma métrica objetiva observada no teste (tempo ou taxa de erro, com os valores) e justifica a escolha. Metade: indica uma métrica objetiva sem os valores ou sem justificativa. Zero: em branco, indica preferência ou quantidade de recursos como métrica.'),
      (v_atividade, 15, 1, 'Explique por que o designer precisa justificar cada mudança.', 0.2, 'Porque o designer precisa justificar cada mudança para clientes e programadores, mostrando por que o botão mudou de lugar e não apenas que mudou.', 'Nota cheia: diz que a justificativa é necessária para explicar a decisão a clientes e programadores. Metade: diz que justificar ajuda, sem citar quem precisa da justificativa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 2, 'Explique o que o documento de melhorias liga entre si.', 0.4, 'O documento liga o fato observado (o usuário travou) à decisão técnica (por exemplo, aumento da fonte e do contraste).', 'Nota cheia: diz que liga o fato observado à decisão técnica. Metade: diz que liga as duas coisas, sem o exemplo ou sem a ideia de fato observado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 3, 'Explique como esse registro protege o projeto contra palpites.', 0.4, 'O registro protege o projeto contra palpites, porque toda mudança fica amparada por um dado observado e por uma métrica, e não apenas pela vontade de quem a propôs.', 'Nota cheia: explica que cada mudança fica amparada em dado observado, e não em palpite. Metade: diz que protege, sem explicar o dado observado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 1, 'Descreva o problema detectado no teste da Versão 1.', 0.2, 'Usuários mais velhos tocavam repetidamente em datas erradas no calendário e desistiam da marcação.', 'Nota cheia: descreve os toques repetidos em datas erradas e a desistência. Metade: descreve só um dos dois (toques errados ou desistência). Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 2, 'Descreva o diagnóstico técnico e a ação tomada na Versão 2.', 0.4, 'Diagnóstico técnico: área de clique menor que 24 px e espaçamento nulo entre os números. Ação na Versão 2: botões estilo pílula com 48 px de altura e 12 px de folga entre eles.', 'Nota cheia: indica o diagnóstico (área pequena e falta de espaçamento) e a ação (botões maiores com folga). Metade: indica só o diagnóstico ou só a ação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 3, 'Explique como o resultado validado comprova que a ação funcionou.', 0.4, 'No segundo ciclo de testes, com a mesma faixa etária, o número de toques errados caiu a zero. Esse resultado validado comprova que a ação corrigiu o problema observado.', 'Nota cheia: diz que o novo teste com o mesmo público mostrou zero toques errados e que isso comprova a correção. Metade: cita o resultado, sem ligar à comprovação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 1, 'Explique qual é o papel de quem apresenta o esboço durante o teste.', 0.2, 'Quem apresenta o esboço deve apenas observar e registrar, sem falar nem ajudar, para que o teste mostre a dificuldade real de quem testa.', 'Nota cheia: diz que quem apresenta observa sem interferir, para revelar a dificuldade real. Metade: diz que deve observar, sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 2, 'Explique por que você não deve dar dicas ao colega durante a tarefa.', 0.4, 'Dar dicas muda o comportamento do colega e esconde as falhas da tela, pois ele deixa de encontrar sozinho o problema, que é o que o teste precisa revelar.', 'Nota cheia: explica que a dica esconde a falha e impede o teste de revelar o problema real. Metade: diz que a dica atrapalha, sem explicar o efeito no teste. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 3, 'Descreva como registrar os momentos de hesitação para alimentar a Versão 2.', 0.4, 'Anotar os momentos de hesitação do colega durante o teste (por exemplo, dois momentos, como pede a aula), com o horário ou a etapa e o que aconteceu, para alimentar a Versão 2.', 'Nota cheia: descreve o registro das hesitações com o momento ou a etapa e o que foi observado, para a Versão 2. Metade: diz que anota, sem o detalhe do momento ou do que foi observado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 1, 'Explique o critério de relevância da tarefa e aplique-o a um dos pedidos.', 0.2, 'O critério de relevância pergunta se o pedido ajuda ou atrapalha o objetivo central da tela e prioriza o que desbloqueia o fluxo principal. Exemplo: o pedido de menos botões pode ser relevante se remove ruído do fluxo de marcação.', 'Nota cheia: explica o critério de relevância e o aplica a um dos pedidos com coerência. Metade: explica o critério, sem aplicá-lo, ou aplica de forma vaga. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 2, 'Explique a diferença entre uma queixa isolada e uma dor coletiva, usando o critério de frequência.', 0.4, 'Uma queixa isolada vem de uma pessoa só; uma dor coletiva aparece em vários voluntários que travaram no mesmo ponto. A frequência indica o que deve ser priorizado.', 'Nota cheia: diferencia queixa isolada (uma pessoa) de dor coletiva (vários voluntários) e liga à frequência. Metade: diferencia as duas, sem ligar à frequência. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 3, 'Explique por que a viabilidade técnica entra na decisão final.', 0.4, 'A viabilidade técnica mostra se a mudança é realizável com os padrões de tela disponíveis e se não cria complexidade desnecessária. Um pedido útil, mas impossível ou muito custoso, não deve entrar na Versão 2 sem avaliação.', 'Nota cheia: explica que a viabilidade verifica se a mudança é realizável e não cria complexidade desnecessária, e que isso pesa na decisão final. Metade: diz que a viabilidade importa, sem explicar o critério. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 1, 'Explique o que o teste está revelando quando o usuário não acha o botão sozinho.', 0.2, 'Quando o usuário não acha o botão sozinho, o teste revela que a interface falhou: o botão não comunica bem a ação, e a tela precisa de ajuste.', 'Nota cheia: diz que a interface falhou e precisa de ajuste, e não que o usuário é o culpado. Metade: diz que há falha, sem a conclusão de ajuste. Zero: em branco, culpa o usuário ou fora do tema.'),
      (v_atividade, 19, 2, 'Explique por que a explicação oral não resolve o problema da interface.', 0.4, 'A explicação oral não corrige a interface: quem usa o produto não terá o professor ou a equipe ao lado, e a tela continua confusa para todos os próximos usuários.', 'Nota cheia: explica que a explicação oral não muda a interface e não serve a usuários futuros. Metade: diz que a explicação não resolve, sem o motivo. Zero: em branco, aceita a sugestão ou fora do tema.'),
      (v_atividade, 19, 3, 'Indique a ação técnica que a equipe deve tomar.', 0.4, 'A equipe deve alterar a tela (por exemplo, dar mais destaque ao botão de confirmação, com contraste e posição melhores) e testar de novo com a Versão 2.', 'Nota cheia: indica ajuste técnico no botão ou no layout e novo teste. Metade: indica o ajuste, sem o novo teste. Zero: em branco, mantém o layout ou fora do tema.'),
      (v_atividade, 20, 1, 'Cite uma regra do ciclo de melhoria e explique-a com suas palavras.', 0.2, 'Uma regra do ciclo é, por exemplo: "O usuário sempre tem razão sobre a própria dor", ou "Protótipos rápidos diminuem custos", ou "Toda versão precisa de registro documental". O aluno deve explicar a regra com suas palavras.', 'Nota cheia: cita uma das regras da aula e a explica com suas palavras. Metade: cita a regra, sem explicar, ou explica uma ideia parecida sem citá-la. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 2, 'Explique por que o usuário sempre tem razão sobre a própria dor e como isso orienta a tela.', 0.4, 'O usuário tem razão sobre a própria dor porque ele é quem sente a dificuldade ao usar a tela; se ele travou, a interface precisa de clareza. Isso orienta a tela a ser ajustada para o problema real, e não para a opinião de quem a projetou.', 'Nota cheia: explica que quem sente a dor é o usuário e que a interface deve ser ajustada a partir dela. Metade: diz que o usuário tem razão, sem ligar à orientação da tela. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 3, 'Explique como a postura de respeito e escuta, ao testar o trabalho de um colega, contribui para o resultado.', 0.4, 'Respeito e escuta permitem receber críticas construtivas, acolher propostas diferentes e apontar o que causou dúvida sem ridicularizar o trabalho do colega. Isso torna o teste mais útil e o projeto melhor, porque o design é uma construção coletiva.', 'Nota cheia: explica que respeito e escuta tornam o teste mais útil, com críticas construtivas, sem ridicularizar o autor. Metade: diz que a postura ajuda, sem explicar como. Zero: em branco, errado ou fora do tema.');
end $$;
